  public void testElementwiseSparseToSparse(@ForAll(sampleSize = 20) @InRange(minInt = 0, maxInt = 10) int sparseIndex1,
                                            @ForAll(sampleSize = 10) double val1,
                                            @ForAll(sampleSize = 20) @InRange(minInt = 0, maxInt = 10) int sparseIndex2,
                                            @ForAll(sampleSize = 10) double val2) {
    ConcatVector v1 = new ConcatVector(1);
    v1.setSparseComponent(0, sparseIndex1, val1);
    ConcatVector v2 = new ConcatVector(1);
    v2.setSparseComponent(0, sparseIndex2, val2);

    v1.elementwiseProductInPlace(v2);
    for (int i = 0; i < 10; i++) {
      double expected = 0.0f;
      if (i == sparseIndex1 && i == sparseIndex2) expected = val1 * val2;
      assertEquals(expected, v1.getValueAt(0, i), 5.0e-4);
    }
  }

  @Theory
  public void testMap(@ForAll(sampleSize = 50) @From(DenseTestVectorGenerator.class) DenseTestVector d1) {
    d1.vector.mapInPlace(x -> (x * Math.sqrt(x)));
    d1.map(x -> (x * Math.sqrt(x)));
    for (int i = 0; i < d1.values.length; i++) {
      for (int j = 0; j < d1.values[i].length; j++) {
        assertEquals(d1.values[i][j], d1.vector.getValueAt(i, j), 5.0e-4);
      }
    }
  }

  @Theory
  public void testValueEquals(@ForAll(sampleSize = 50) @From(DenseTestVectorGenerator.class) DenseTestVector d1) {
    ConcatVector clone = d1.vector.deepClone();
    assertTrue(clone.valueEquals(d1.vector, 1.0e-5));
    assertTrue(d1.vector.valueEquals(clone, 1.0e-5));
    assertTrue(d1.vector.valueEquals(d1.vector, 1.0e-5));
    assertTrue(clone.valueEquals(clone, 1.0e-5));

    Random r = new Random();

    int size = clone.getNumberOfComponents();
    if (size > 0) {
      clone.addVectorInPlace(d1.vector, 1.0);

      // If the clone is a 0 vector
      boolean isZero = true;
      for (double[] arr : d1.values) {
        for (double d : arr) if (d != 0) isZero = false;
      }
      if (isZero) {
        assertTrue(clone.valueEquals(d1.vector, 1.0e-5));
        assertTrue(d1.vector.valueEquals(clone, 1.0e-5));
      } else {
        assertFalse(clone.valueEquals(d1.vector, 1.0e-5));
        assertFalse(d1.vector.valueEquals(clone, 1.0e-5));
      }
      assertTrue(d1.vector.valueEquals(d1.vector, 1.0e-5));
      assertTrue(clone.valueEquals(clone, 1.0e-5));

      // refresh the clone

      clone = d1.vector.deepClone();

      int tinker = r.nextInt(size);
      d1.vector.setDenseComponent(tinker, new double[]{0, 0, 1});
      clone.setSparseComponent(tinker, 2, 1);

      assertTrue(d1.vector.valueEquals(clone, 1.0e-5));
      assertTrue(clone.valueEquals(d1.vector, 1.0e-5));
    }
  }

  /**
   * Created by keenon on 12/6/14.
   * <p>
   * DenseVector with obviously correct semantics for checking the MultiVector against.
   */
  public static class DenseTestVector {
    public double[][] values;
    public ConcatVector vector;

    public DenseTestVector(double[][] values, ConcatVector vector) {
      this.values = values;
      this.vector = vector;
    }

    public double trueInnerProduct(DenseTestVector testVector) {
      double sum = 0.0f;
      for (int i = 0; i < Math.min(values.length, testVector.values.length); i++) {
        for (int j = 0; j < Math.min(values[i].length, testVector.values[i].length); j++) {
          sum += values[i][j] * testVector.values[i][j];
        }
      }
      return sum;
    }

    public void map(DoubleUnaryOperator fn) {
      for (int i = 0; i < values.length; i++) {
        for (int j = 0; j < values[i].length; j++) {
          values[i][j] = fn.applyAsDouble(values[i][j]);
        }
      }
    }

    @Override
    public String toString() {
      return vector.toString();
    }
  }

  /**
   * Created by keenon on 12/6/14.
   * <p>
   * Handles generating the inputs for Quickcheck against the MultiVector
   */
  public static class DenseTestVectorGenerator extends Generator<DenseTestVector> {
    public DenseTestVectorGenerator(Class<DenseTestVector> type) {
      super(type);
    }

    static final int SPARSE_VECTOR_LENGTH = 5;

    public DenseTestVectorGenerator() {
      super(DenseTestVector.class);
    }

    @Override
    public DenseTestVector generate(SourceOfRandomness sourceOfRandomness, GenerationStatus generationStatus) {
      int length = sourceOfRandomness.nextInt(10);
      double[][] trueValues = new double[length][];
      boolean[] sparse = new boolean[length];
      int[] sizes = new int[length];

      // Generate sizes in advance, so we can pass the clues on to the constructor for the multivector
      for (int i = 0; i < length; i++) {
        boolean isSparse = sourceOfRandomness.nextBoolean();
        sparse[i] = isSparse;
        if (isSparse) {
          sizes[i] = -1;
        } else {
          int componentLength = sourceOfRandomness.nextInt(SPARSE_VECTOR_LENGTH);
          sizes[i] = componentLength;
        }
      }

      ConcatVector mv = new ConcatVector(length);
      for (int i = 0; i < length; i++) {
        if (sparse[i]) {
          trueValues[i] = new double[SPARSE_VECTOR_LENGTH];
          int sparseIndex = sourceOfRandomness.nextInt(SPARSE_VECTOR_LENGTH);
          double sparseValue = sourceOfRandomness.nextDouble();
          trueValues[i][sparseIndex] = sparseValue;
          mv.setSparseComponent(i, sparseIndex, sparseValue);
        } else {
          trueValues[i] = new double[sizes[i]];
          // Ensure we have some null components in our generated vector
          if (sizes[i] > 0) {
            for (int j = 0; j < sizes[i]; j++) {
              trueValues[i][j] = sourceOfRandomness.nextDouble();
            }
            mv.setDenseComponent(i, trueValues[i]);
          }
        }
      }

      return new DenseTestVector(trueValues, mv);
    }
  }
}

package edu.stanford.nlp.loglinear.model;

import com.pholser.junit.quickcheck.ForAll;
import com.pholser.junit.quickcheck.From;
import com.pholser.junit.quickcheck.generator.GenerationStatus;
import com.pholser.junit.quickcheck.generator.Generator;
import com.pholser.junit.quickcheck.generator.InRange;
import com.pholser.junit.quickcheck.random.SourceOfRandomness;
import org.junit.contrib.theories.Theories;
import org.junit.contrib.theories.Theory;
import org.junit.runner.RunWith;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Created on 8/9/15.
 * @author keenon
 * <p>
 * This will attempt to quickcheck the ConcatVectorTable class. There isn't much functionality in there, so this is a short test
 * suite.
 */
@RunWith(Theories.class)
public class ConcatVectorTableTest {

  public static ConcatVectorTable convertArrayToVectorTable(ConcatVector[][][] factor3) {
    int[] neighborSizes = new int[]{
        factor3.length,
        factor3[0].length,
        factor3[0][0].length
    };
    ConcatVectorTable concatVectorTable = new ConcatVectorTable(neighborSizes);
    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          final int iF = i;
          final int jF = j;
          final int kF = k;
          concatVectorTable.setAssignmentValue(new int[]{i, j, k}, () -> factor3[iF][jF][kF]);
        }
      }
    }
    return concatVectorTable;
  }

  @Theory
  public void testCache(@ForAll(sampleSize = 50) @From(FeatureFactorGenerator.class) ConcatVector[][][] factor3,
                        @ForAll(sampleSize = 10) @InRange(minInt = 1, maxInt = 30) int numUses) throws IOException {
    int[] dimensions = new int[]{factor3.length, factor3[0].length, factor3[0][0].length};

    final int[][][] thunkHits = new int[dimensions[0]][dimensions[1]][dimensions[2]];

    ConcatVectorTable table = new ConcatVectorTable(dimensions);
    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          int[] assignment = new int[]{i, j, k};
          table.setAssignmentValue(assignment, () -> {
            thunkHits[assignment[0]][assignment[1]][assignment[2]] += 1;
            return factor3[assignment[0]][assignment[1]][assignment[2]];
          });
        }
      }
    }

    // Pre-cacheing
    for (int n = 0; n < numUses; n++) {
      for (int i = 0; i < factor3.length; i++) {
        for (int j = 0; j < factor3[0].length; j++) {
          for (int k = 0; k < factor3[0][0].length; k++) {
            int[] assignment = new int[]{i, j, k};
            table.getAssignmentValue(assignment).get();
          }
        }
      }
    }

    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          assertEquals(numUses, thunkHits[i][j][k]);
        }
      }
    }

    table.cacheVectors();

    // Cached
    for (int n = 0; n < numUses; n++) {
      for (int i = 0; i < factor3.length; i++) {
        for (int j = 0; j < factor3[0].length; j++) {
          for (int k = 0; k < factor3[0][0].length; k++) {
            int[] assignment = new int[]{i, j, k};
            table.getAssignmentValue(assignment).get();
          }
        }
      }
    }

    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          assertEquals(numUses + 1, thunkHits[i][j][k]);
        }
      }
    }

    table.releaseCache();

    // Post-cacheing
    for (int n = 0; n < numUses; n++) {
      for (int i = 0; i < factor3.length; i++) {
        for (int j = 0; j < factor3[0].length; j++) {
          for (int k = 0; k < factor3[0][0].length; k++) {
            int[] assignment = new int[]{i, j, k};
            table.getAssignmentValue(assignment).get();
          }
        }
      }
    }

    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          assertEquals((2 * numUses) + 1, thunkHits[i][j][k]);
        }
      }
    }
  }

  @Theory
  public void testProtoTable(@ForAll(sampleSize = 50) @From(FeatureFactorGenerator.class) ConcatVector[][][] factor3) throws IOException {
    ConcatVectorTable concatVectorTable = convertArrayToVectorTable(factor3);

    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    concatVectorTable.writeToStream(byteArrayOutputStream);
    byteArrayOutputStream.close();

    byte[] bytes = byteArrayOutputStream.toByteArray();

    ByteArrayInputStream byteArrayInputStream = new ByteArrayInputStream(bytes);

    ConcatVectorTable recovered = ConcatVectorTable.readFromStream(byteArrayInputStream);
    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          assertTrue(factor3[i][j][k].valueEquals(recovered.getAssignmentValue(new int[]{i, j, k}).get(), 1.0e-5));
        }
      }
    }
    assertTrue(concatVectorTable.valueEquals(recovered, 1.0e-5));
  }

  @Theory
  public void testCloneTable(@ForAll(sampleSize = 50) @From(FeatureFactorGenerator.class) ConcatVector[][][] factor3) throws IOException {
    ConcatVectorTable concatVectorTable = convertArrayToVectorTable(factor3);

    ConcatVectorTable cloned = concatVectorTable.cloneTable();
    for (int i = 0; i < factor3.length; i++) {
      for (int j = 0; j < factor3[0].length; j++) {
        for (int k = 0; k < factor3[0][0].length; k++) {
          assertTrue(factor3[i][j][k].valueEquals(cloned.getAssignmentValue(new int[]{i, j, k}).get(), 1.0e-5));
        }
      }
    }
    assertTrue(concatVectorTable.valueEquals(cloned, 1.0e-5));
  }

  public static class FeatureFactorGenerator extends Generator<ConcatVector[][][]> {
    public FeatureFactorGenerator(Class<ConcatVector[][][]> type) {
      super(type);
    }

    @Override
    public ConcatVector[][][] generate(SourceOfRandomness sourceOfRandomness, GenerationStatus generationStatus) {
      int l = sourceOfRandomness.nextInt(10) + 1;
      int m = sourceOfRandomness.nextInt(10) + 1;
      int n = sourceOfRandomness.nextInt(10) + 1;
      ConcatVector[][][] factor3 = new ConcatVector[l][m][n];
      for (int i = 0; i < factor3.length; i++) {
        for (int j = 0; j < factor3[0].length; j++) {
          for (int k = 0; k < factor3[0][0].length; k++) {
            int numComponents = sourceOfRandomness.nextInt(7);
            ConcatVector v = new ConcatVector(numComponents);
            for (int x = 0; x < numComponents; x++) {
              if (sourceOfRandomness.nextBoolean()) {
                v.setSparseComponent(x, sourceOfRandomness.nextInt(32), sourceOfRandomness.nextDouble());
              } else {
                double[] val = new double[sourceOfRandomness.nextInt(12)];
                for (int y = 0; y < val.length; y++) {
                  val[y] = sourceOfRandomness.nextDouble();
                }
                v.setDenseComponent(x, val);
              }
            }
            factor3[i][j][k] = v;
          }
        }
      }
      return factor3;
    }
  }
}

package edu.stanford.nlp.international.arabic; 
import edu.stanford.nlp.util.logging.Redwood;

import java.io.*;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import edu.stanford.nlp.international.morph.MorphoFeatureSpecification;
import edu.stanford.nlp.international.morph.MorphoFeatures;

/**
 * Extracts morphosyntactic features from BAMA/SAMA analyses. Compatible with both the
 * long tags in the ATB and the output of MADA.
 *
 * @author Spence Green
 *
 */
public class ArabicMorphoFeatureSpecification extends MorphoFeatureSpecification  {

  /** A logger for this class */
  private static Redwood.RedwoodChannels log = Redwood.channels(ArabicMorphoFeatureSpecification.class);

  private static final long serialVersionUID = 4448045447200922076L;

  private static final String[] defVals = {"I", "D"};
  private static final String[] caseVals = {"NOM","ACC","GEN"};
  private static final String[] genVals = {"M","F"};
  private static final String[] numVals = {"SG","DU","PL"};
  private static final String[] perVals = {"1","2","3"};
  private static final String[] possVals = {"POSS"};
  private static final String[] voiceVals = {"ACT","PASS"};
  private static final String[] moodVals = {"I","S","J"};
  private static final String[] tenseVals = {"PAST","PRES","IMP"};

  // Standard feature tuple (e.g., "3MS", "1P", etc.)
  private static final Pattern pFeatureTuple = Pattern.compile("(\\d\\p{Upper}\\p{Upper}?)");

  // Demonstrative pronouns do not have number
  private static final Pattern pDemPronounFeatures = Pattern.compile("DEM_PRON(.+)");

  //Verbal patterns
  private static final Pattern pVerbMood = Pattern.compile("MOOD|SUBJ");
  private static final Pattern pMood = Pattern.compile("_MOOD:([ISJ])");
  private static final Pattern pVerbTenseMarker = Pattern.compile("IV|PV|CV");
  private static final Pattern pNounNoMorph = Pattern.compile("PROP|QUANT");

  @Override
  public List<String> getValues(MorphoFeatureType feat) {
    if(feat == MorphoFeatureType.DEF)
      return Arrays.asList(defVals);
    else if(feat == MorphoFeatureType.CASE) {
      throw new RuntimeException(this.getClass().getName() + ": Case is presently unsupported!");
//      return Arrays.asList(caseVals);
    } else if(feat == MorphoFeatureType.GEN)
      return Arrays.asList(genVals);
    else if(feat == MorphoFeatureType.NUM)
      return Arrays.asList(numVals);
    else if(feat == MorphoFeatureType.PER)
      return Arrays.asList(perVals);
    else if(feat == MorphoFeatureType.POSS)
      return Arrays.asList(possVals);
    else if(feat == MorphoFeatureType.VOICE)
      return Arrays.asList(voiceVals);
    else if(feat == MorphoFeatureType.MOOD)
      return Arrays.asList(moodVals);
    else if(feat == MorphoFeatureType.TENSE)
      return Arrays.asList(tenseVals);
    else
      throw new IllegalArgumentException("Arabic does not support feature type: " + feat.toString());
  }

  /**
   * Hand-written rules to convert SAMA analyses to feature structures.
   */
  @Override
  public MorphoFeatures strToFeatures(String spec) {
    MorphoFeatures features = new ArabicMorphoFeatures();

    // Check for the boundary symbol
    if(spec == null || spec.equals("")) {
      return features;
    }
    //Possessiveness
    if(isActive(MorphoFeatureType.POSS) && spec.contains("POSS")) {
      features.addFeature(MorphoFeatureType.POSS,possVals[0]);
    }

    //Nominals and pronominals. Mona ignores Pronominals in ERTS, but they seem to help...
    // NSUFF -- declinable nominals
    // VSUFF -- enclitic pronominals
    // PRON -- ordinary pronominals
    if(spec.contains("NSUFF") || spec.contains("NOUN") || spec.contains("ADJ")) {
      // Nominal phi feature indicators are different than the indicators
      // that we process with processInflectionalFeatures()
      if(isActive(MorphoFeatureType.NGEN)) {
        if(spec.contains("FEM")) {
          features.addFeature(MorphoFeatureType.NGEN, genVals[1]);
        } else if(spec.contains("MASC") || !pNounNoMorph.matcher(spec).find()) {
          features.addFeature(MorphoFeatureType.NGEN, genVals[0]);
        }
      }

      // WSGDEBUG -- Number for nominals only
      if(isActive(MorphoFeatureType.NNUM)) {
        if(spec.contains("DU")) {
          features.addFeature(MorphoFeatureType.NNUM, numVals[1]);
        } else if(spec.contains("PL")) {
          features.addFeature(MorphoFeatureType.NNUM, numVals[2]);
        } else if (!pNounNoMorph.matcher(spec).find()){ // (spec.contains("SG"))
          features.addFeature(MorphoFeatureType.NNUM, numVals[0]);
        }
      }

      //Definiteness
      if(isActive(MorphoFeatureType.DEF)) {
        if (spec.contains("DET")) {
          features.addFeature(MorphoFeatureType.DEF, defVals[1]);
        } else if (!pNounNoMorph.matcher(spec).find()){
          features.addFeature(MorphoFeatureType.DEF, defVals[0]);
        }
      }

      // Proper nouns (probably a stupid feature)
      if (isActive(MorphoFeatureType.PROP)) {
        if (spec.contains("PROP")) {
          features.addFeature(MorphoFeatureType.PROP,"");
        }
      }

    } else if(spec.contains("PRON") || (spec.contains("VSUFF_DO") && !pVerbMood.matcher(spec).find())) {
      if(spec.contains("DEM_PRON")) {
        features.addFeature(MorphoFeatureType.DEF, defVals[0]);
        Matcher m = pDemPronounFeatures.matcher(spec);
        if (m.find()) {
          spec = m.group(1);
          processInflectionalFeaturesHelper(features, spec);
        }

      } else {
        processInflectionalFeatures(features, spec);
      }

    // Verbs (marked for tense)
    } else if(pVerbTenseMarker.matcher(spec).find()) {

      // Tense feature
      if(isActive(MorphoFeatureType.TENSE)) {
        if(spec.contains("PV"))
          features.addFeature(MorphoFeatureType.TENSE, tenseVals[0]);
        else if(spec.contains("IV"))
          features.addFeature(MorphoFeatureType.TENSE, tenseVals[1]);
        else if(spec.contains("CV"))
          features.addFeature(MorphoFeatureType.TENSE, tenseVals[2]);
      }

      // Inflectional features
      processInflectionalFeatures(features, spec);

      if(isActive(MorphoFeatureType.MOOD)) {
        Matcher moodMatcher = pMood.matcher(spec);
        if(moodMatcher.find()) {
          String moodStr = moodMatcher.group(1);
          switch (moodStr) {
            case "I":
              features.addFeature(MorphoFeatureType.MOOD, moodVals[0]);
              break;
            case "S":
              features.addFeature(MorphoFeatureType.MOOD, moodVals[1]);
              break;
            case "J":
              features.addFeature(MorphoFeatureType.MOOD, moodVals[2]);
              break;
          }
        }
      }

      if(isActive(MorphoFeatureType.VOICE)) {
        if(spec.contains("PASS")) {
          features.addFeature(MorphoFeatureType.VOICE, voiceVals[1]);
        } else {
          features.addFeature(MorphoFeatureType.VOICE, voiceVals[0]);
        }
      }
    }
    return features;
  }

  /**
   * Extract features from a standard phi feature specification.
   *
   * @param feats
   * @param spec
   */
  private void processInflectionalFeatures(MorphoFeatures feats, String spec) {
    // Extract the feature tuple
    Matcher m = pFeatureTuple.matcher(spec);
    if (m.find()) {
      spec = m.group(1);
      processInflectionalFeaturesHelper(feats, spec);
    }
  }

  private void processInflectionalFeaturesHelper(MorphoFeatures feats, String spec) {
    if(isActive(MorphoFeatureType.GEN)) {
      if(spec.contains("M"))
        feats.addFeature(MorphoFeatureType.GEN, genVals[0]);
      else if(spec.contains("F"))
        feats.addFeature(MorphoFeatureType.GEN, genVals[1]);
    }

    if(isActive(MorphoFeatureType.NUM)) {
      if(spec.endsWith("S"))
        feats.addFeature(MorphoFeatureType.NUM, numVals[0]);
      else if(spec.endsWith("D"))
        feats.addFeature(MorphoFeatureType.NUM, numVals[1]);
      else if(spec.endsWith("P"))
        feats.addFeature(MorphoFeatureType.NUM, numVals[2]);
    }

    if(isActive(MorphoFeatureType.PER)) {
      if(spec.contains("1"))
        feats.addFeature(MorphoFeatureType.PER, perVals[0]);
      else if(spec.contains("2"))
        feats.addFeature(MorphoFeatureType.PER, perVals[1]);
      else if(spec.contains("3"))
        feats.addFeature(MorphoFeatureType.PER, perVals[2]);
    }
  }

  /**
   * Converts features specifications to labels for tagging
   *
   * @author Spence Green
   *
   */
  public static class ArabicMorphoFeatures extends MorphoFeatures {

    private static final long serialVersionUID = -4611776415583633186L;

    @Override
    public MorphoFeatures fromTagString(String str) {
      String[] feats = str.split("\\-");
      MorphoFeatures mFeats = new ArabicMorphoFeatures();
      // First element is the base POS
//      String baseTag = feats[0];
      for(int i = 1; i < feats.length; i++) {
        String[] keyValue = feats[i].split(KEY_VAL_DELIM);
        if(keyValue.length != 2) continue;
        MorphoFeatureType fName = MorphoFeatureType.valueOf(keyValue[0].trim());
        mFeats.addFeature(fName, keyValue[1].trim());
      }
      return mFeats;
    }

    @Override
    public String getTag(String basePartOfSpeech) {
      StringBuilder sb = new StringBuilder(basePartOfSpeech);
      // Iterate over feature list so that features are added in the same order
      // for every feature spec.
      for (MorphoFeatureType feat : MorphoFeatureType.values()) {
        if (hasFeature(feat)) {
          sb.append(String.format("-%s:%s",feat,fSpec.get(feat)));
        }
      }
      return sb.toString();
    }
  }

  /**
   * For debugging. Converts a set of long tags (BAMA analyses as in the ATB) to their morpho
   * feature specification. The input file should have one long tag per line.
   *
   * @param args
   */
  public static void main(String[] args) {
    if(args.length != 2) {
      System.err.printf("Usage: java %s filename feats%n", ArabicMorphoFeatureSpecification.class.getName());
      System.exit(-1);
    }

    MorphoFeatureSpecification fSpec = new ArabicMorphoFeatureSpecification();
    String[] feats = args[1].split(",");
    for(String feat : feats) {
      MorphoFeatureType fType = MorphoFeatureType.valueOf(feat);
      fSpec.activate(fType);
    }

    File fName = new File(args[0]);
    try {
      BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(fName)));

      int nLine = 0;
      for(String line;(line = br.readLine()) != null; nLine++) {
        MorphoFeatures mFeats = fSpec.strToFeatures(line.trim());
        System.out.printf("%s\t%s%n", line.trim(), mFeats.toString());
      }
      br.close();
      System.out.printf("%nRead %d lines%n",nLine);

    } catch (FileNotFoundException e) {
      e.printStackTrace();
    } catch (IOException e) {
      e.printStackTrace();
    }
  }
}

package edu.stanford.nlp.time;

import org.junit.Test;

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Checks that the SUTime rule files in the source tree match the copies shipped in the
 * models jar.
 *
 * <p>The pipeline loads its grammar from {@code edu/stanford/nlp/models/sutime/} on the
 * classpath, which comes from the models jar. The copies under
 * {@code src/edu/stanford/nlp/time/rules/} are the editable master, and nothing in the
 * build connects the two. Editing a rule in the source tree therefore has no effect on
 * anything until the models jar is rebuilt, and the two can sit out of step
 * indefinitely without any test noticing.
 *
 * <p>That is worth one test rather than a second copy of every behavioural test. Tests
 * that exercise rule behaviour point at the source tree, because that is the copy being
 * edited and a red build there means a real mistake. This test is the only one that
 * cares about the jar, and when it fails the action is always the same: rebuild the
 * models jar. Duplicating the behavioural tests against the jar would instead leave
 * every new rule with a test that fails from the day it is written until release, which
 * teaches people to ignore it.
 *
 * <p>This is an ITest because it needs the models jar on the classpath.
 */
public class SUTimeRuleSyncITest {

  /** The editable master copies. */
  private static final String SOURCE_DIR = "src/edu/stanford/nlp/time/rules";

  /** Where the pipeline actually loads them from. */
  private static final String CLASSPATH_DIR = "/edu/stanford/nlp/models/sutime";

  @Test
  public void testSourceRulesMatchModelsJar() throws IOException {
    File sourceDir = new File(SOURCE_DIR);
    assertTrue("cannot find " + sourceDir.getAbsolutePath()
                    + " -- this test expects to run from the repository root",
            sourceDir.isDirectory());

    File[] sourceFiles = sourceDir.listFiles((d, name) -> name.endsWith(".sutime.txt"));
    assertNotNull(sourceFiles);
    assertTrue("no rule files found in " + SOURCE_DIR, sourceFiles.length > 0);
    Arrays.sort(sourceFiles);

    List<String> problems = new ArrayList<>();
    for (File sourceFile : sourceFiles) {
      String resource = CLASSPATH_DIR + '/' + sourceFile.getName();
      List<String> shipped = readClasspath(resource);
      if (shipped == null) {
        problems.add(sourceFile.getName() + ": not present at " + resource
                + " -- a new rule file has to be added to the models jar");
        continue;
      }
      List<String> master = Files.readAllLines(sourceFile.toPath(), StandardCharsets.UTF_8);
      String difference = firstDifference(master, shipped);
      if (difference != null) {
        problems.add(sourceFile.getName() + ": " + difference);
      }
    }

    if ( ! problems.isEmpty()) {
      StringBuilder sb = new StringBuilder(
              "SUTime rules in the source tree do not match the models jar. Rebuild the "
                      + "models jar so the shipped grammar picks up these edits.");
      for (String problem : problems) {
        sb.append("\n  ").append(problem);
      }
      fail(sb.toString());
    }
  }

  /**
   * Read a resource from the classpath only. Deliberately not IOUtils, which falls back
   * to the filesystem and would happily return the source copy we are comparing against.
   */
  private static List<String> readClasspath(String resource) throws IOException {
    try (InputStream in = SUTimeRuleSyncITest.class.getResourceAsStream(resource)) {
      if (in == null) {
        return null;
      }
      List<String> lines = new ArrayList<>();
      try (BufferedReader br = new BufferedReader(
              new InputStreamReader(in, StandardCharsets.UTF_8))) {
        String line;
        while ((line = br.readLine()) != null) {
          lines.add(line);
        }
      }
      return lines;
    }
  }

  /**
   * Describe the first line that differs, or null if the two agree. Line endings are
   * already normalised away by readLine, and trailing whitespace is ignored, so a
   * checkout with different line endings from the jar does not fail here.
   */
  private static String firstDifference(List<String> master, List<String> shipped) {
    int shared = Math.min(master.size(), shipped.size());
    for (int i = 0; i < shared; i++) {
      String a = stripTrailing(master.get(i));
      String b = stripTrailing(shipped.get(i));
      if ( ! a.equals(b)) {
        return "line " + (i + 1) + " differs\n      source: " + a + "\n      jar:    " + b;
      }
    }
    if (master.size() != shipped.size()) {
      return "source has " + master.size() + " lines, jar has " + shipped.size();
    }
    return null;
  }

  private static String stripTrailing(String s) {
    int end = s.length();
    while (end > 0 && Character.isWhitespace(s.charAt(end - 1))) {
      end--;
    }
    return s.substring(0, end);
  }

}

package edu.stanford.nlp.international.morph;

import java.io.Serializable;

import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

import edu.stanford.nlp.util.Generics;
import edu.stanford.nlp.util.Pair;

/**
 * Morphological feature specification for surface forms in a given language.
 * Currently supported feature names are the values of MorphFeatureType.
 * 
 * @author Spence Green
 *
 */
public abstract class MorphoFeatureSpecification implements Serializable {

  private static final long serialVersionUID = -5720683653931585664L;

  //Delimiter for associating a surface form with a morphological analysis, e.g.,
  //
  //     his~#PRP_3ms
  //
  public static final String MORPHO_MARK = "~#";

  public static final String LEMMA_MARK = "|||";

  public static final String NO_ANALYSIS = "XXX";

  // WSGDEBUG --
  //   Added NNUM and NGEN for nominals in Arabic
  public static enum MorphoFeatureType {TENSE,DEF,ASP,MOOD,NNUM,NUM, NGEN, GEN,CASE,PER,POSS,VOICE,OTHER,PROP, ANIMACY,
    TRANSITIVITY, VERBFORM, VARIANT, DEGREE, GENDER };

  protected final Set<MorphoFeatureType> activeFeatures;

  public MorphoFeatureSpecification() {
    activeFeatures = Generics.newHashSet();
  }

  public void activate(MorphoFeatureType feat) {
    activeFeatures.add(feat);
  }

  public boolean isActive(MorphoFeatureType feat) { return activeFeatures.contains(feat); }

  public abstract List<String> getValues(MorphoFeatureType feat);

  public abstract MorphoFeatures strToFeatures(String spec);

  /**
   * Returns the lemma as pair.first() and the morph analysis as pair.second().
   */
  public static Pair<String,String> splitMorphString(String word, String morphStr) {
    if (morphStr == null || morphStr.trim().equals("")) {
      return new Pair<>(word, NO_ANALYSIS);
    }
    String[] toks = morphStr.split(Pattern.quote(LEMMA_MARK));
    if (toks.length != 2) {
      throw new RuntimeException("Invalid morphology string: " + morphStr);
    }
    return new Pair<>(toks[0], toks[1]);
  }


  @Override
  public String toString() { return activeFeatures.toString(); }
}

package edu.stanford.nlp.international.french; 
import edu.stanford.nlp.util.logging.Redwood;

import java.io.BufferedReader;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;

import edu.stanford.nlp.international.morph.MorphoFeatureSpecification;
import edu.stanford.nlp.international.morph.MorphoFeatures;

/**
 * If MorphoFeatureType.OTHER is active, then the "CC tagset" is produced (see Tbl.2
 * of (Crabbe and Candito, 2008). Additional support exists for GEN, NUM, and PER, which
 * are (mostly) marked in the FTB annotation.
 * <p>
 * The actual CC tag is placed in the altTag field of the MorphoFeatures object.
 * 
 * @author Spence Green
 *
 */
public class FrenchMorphoFeatureSpecification extends MorphoFeatureSpecification  {

  /** A logger for this class */
  private static Redwood.RedwoodChannels log = Redwood.channels(FrenchMorphoFeatureSpecification.class);

  private static final long serialVersionUID = -58379347760106784L;

  public static final String[] genVals = {"M","F"};
  public static final String[] numVals = {"SG","PL"};
  public static final String[] perVals = {"1","2","3"};


  @Override
  public List<String> getValues(MorphoFeatureType feat) {
    if(feat == MorphoFeatureType.GEN)
      return Arrays.asList(genVals);
    else if(feat == MorphoFeatureType.NUM)
      return Arrays.asList(numVals);
    else if(feat == MorphoFeatureType.PER)
      return Arrays.asList(perVals);
    else
      throw new IllegalArgumentException("French does not support feature type: " + feat.toString());
  }

  @Override
  public MorphoFeatures strToFeatures(String spec) {
    MorphoFeatures feats = new MorphoFeatures();

    //Usually this is the boundary symbol
    if(spec == null || spec.equals(""))
      return feats;

    boolean isOtherActive = isActive(MorphoFeatureType.OTHER);

    if(spec.startsWith("ADV")) {
      feats.setAltTag("ADV");
      if(spec.contains("int")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "advint");
        }
        feats.setAltTag("ADVWH");
      }

    } else if(spec.startsWith("A")) {
      feats.setAltTag("ADJ");
      if(spec.contains("int")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "adjint");
        }
        feats.setAltTag("ADJWH");
      }

      addPhiFeatures(feats,spec);

    } else if(spec.equals("CC") || spec.equals("C-C")) {
      if (isOtherActive) {
        feats.addFeature(MorphoFeatureType.OTHER, "Cc");
      }
      feats.setAltTag("CC");

    } else if(spec.equals("CS") || spec.equals("C-S")) {
      if (isOtherActive) {
        feats.addFeature(MorphoFeatureType.OTHER, "Cs");
      }
      feats.setAltTag("CS");

    } else if(spec.startsWith("CL")) {
      feats.setAltTag("CL");
      if(spec.contains("suj") || spec.equals("CL-S-3fp")) {//"CL-S-3fp" is equivalent to suj
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER,"Sbj");
        }
        feats.setAltTag("CLS");

      } else if(spec.contains("obj")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Obj");
        }
        feats.setAltTag("CLO");

      } else if(spec.contains("refl")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Rfl");
        }
        feats.setAltTag("CLR");
      }

      addPhiFeatures(feats,spec);

    } else if(spec.startsWith("D")) {
      feats.setAltTag("DET");
      if(spec.contains("int")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "dint");
        }
        feats.setAltTag("DETWH");
      }

      addPhiFeatures(feats,spec);

    } else if(spec.startsWith("N")) {
      feats.setAltTag("N");//TODO These are usually N-card...make these CD?
      if(spec.contains("P")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Np");
        }
        feats.setAltTag("NPP");

      } else if(spec.contains("C")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Nc");
        }
        feats.setAltTag("NC");
      }

      addPhiFeatures(feats,spec);

    } else if(spec.startsWith("PRO")) {
      feats.setAltTag("PRO");
      if(spec.contains("int")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER,"Ni");
        }
        feats.setAltTag("PROWH");

      } else if(spec.contains("rel")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Nr");
        }
        feats.setAltTag("PROREL");
      }

      addPhiFeatures(feats,spec);

    } else if(spec.startsWith("V")) {
      feats.setAltTag("V");
      if(spec.contains("Y")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER,"Vp");
        }
        feats.setAltTag("VIMP");

      } else if(spec.contains("W")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Vf");
        }
        feats.setAltTag("VINF");

      } else if(spec.contains("S") || spec.contains("T")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Vs");
        }
        feats.setAltTag("VS");

      } else if(spec.contains("K")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Vp");
        }
        feats.setAltTag("VPP");

      } else if(spec.contains("G")) {
        if (isOtherActive) {
          feats.addFeature(MorphoFeatureType.OTHER, "Vr");
        }
        feats.setAltTag("VPR");
      }

      addPhiFeatures(feats,spec);

    } else if(spec.equals("P") || spec.equals("I")) { 
      feats.setAltTag(spec);

    } 
//    else {
//      log.info("Could not map spec: " + spec);
//    }

    return feats;
  }

  private void addPhiFeatures(MorphoFeatures feats, String spec) {
    String[] toks = spec.split("\\-+");

    String morphStr;
    if(toks.length == 3 && toks[0].equals("PRO") && toks[2].equals("neg"))
      morphStr = toks[1];
    else
      morphStr = toks[toks.length-1];

    //wsg2011: The analyses have mixed casing....
    morphStr = morphStr.toLowerCase();

    if(isActive(MorphoFeatureType.GEN)) {
      if(morphStr.contains("m"))
        feats.addFeature(MorphoFeatureType.GEN, genVals[0]);
      else if(morphStr.contains("f"))
        feats.addFeature(MorphoFeatureType.GEN, genVals[1]);
    }

    if(isActive(MorphoFeatureType.PER)) {
      if(morphStr.contains("1"))
        feats.addFeature(MorphoFeatureType.PER, perVals[0]);
      else if(morphStr.contains("2"))
        feats.addFeature(MorphoFeatureType.PER, perVals[1]);
      else if(morphStr.contains("3"))
        feats.addFeature(MorphoFeatureType.PER, perVals[2]);
    }

    if(isActive(MorphoFeatureType.NUM)) {
      if(morphStr.contains("s"))
        feats.addFeature(MorphoFeatureType.NUM, numVals[0]);
      else if(morphStr.contains("p"))
        feats.addFeature(MorphoFeatureType.NUM, numVals[1]);
    }
  }


  /**
   * For debugging
   * 
   * @param args
   */
  public static void main(String[] args) {
    if(args.length != 1) {
      System.err.printf("Usage: java %s file%n", FrenchMorphoFeatureSpecification.class.getName());
      System.exit(-1);
    }

    try {
      BufferedReader br = new BufferedReader(new FileReader(args[0]));
      MorphoFeatureSpecification mfs = new FrenchMorphoFeatureSpecification();

      //Activate all features for debugging
      mfs.activate(MorphoFeatureType.GEN);
      mfs.activate(MorphoFeatureType.NUM);
      mfs.activate(MorphoFeatureType.PER);

      for(String line; (line = br.readLine()) != null;) {
        MorphoFeatures feats = mfs.strToFeatures(line);
        System.out.printf("%s\t%s%n", line.trim(),feats.toString());
      }

      br.close();

    } catch (FileNotFoundException e) {
      e.printStackTrace();
    } catch (IOException e) {
      e.printStackTrace();
    }
  }
}

package edu.stanford.nlp.trees.ud;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.PrintStream;
import java.util.Properties;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import edu.stanford.nlp.io.IOUtils;

/**
 * What UniversalDependenciesConverter writes for a small English treebank.
 *<br>
 * These record the behavior rather than argue for it: the expected values
 * are what the converter produced when the test was written.  That is what
 * makes them useful when something underneath changes, since anything which
 * moves shows up here as a diff.
 *<br>
 * Only the CoNLL-U input path is covered.  The tree input path needs a
 * treebank on disk and does not touch the reader.
 *
 * @author John Bauer
 */
public class UniversalDependenciesConverterTest {

  /**
   * A relative clause, a coordination sharing a preposition, and a
   * multiword token with a misc of its own
   */
  private static final String FIXTURE = String.join("\n",
      "# sent_id = relcl",
      "# text = the man who I saw left",
      "1\tthe\tthe\tDET\tDT\tDefinite=Def\t2\tdet\t_\t_",
      "2\tman\tman\tNOUN\tNN\tNumber=Sing\t6\tnsubj\t_\t_",
      "3\twho\twho\tPRON\tWP\tPronType=Rel\t5\tobj\t_\t_",
      "4\tI\tI\tPRON\tPRP\tNumber=Sing\t5\tnsubj\t_\t_",
      "5\tsaw\tsee\tVERB\tVBD\tTense=Past\t2\tacl:relcl\t_\t_",
      "6\tleft\tleave\tVERB\tVBD\tTense=Past\t0\troot\t_\t_",
      "",
      "# sent_id = coord",
      "# text = He works in Paris and London.",
      "1\tHe\the\tPRON\tPRP\tNumber=Sing\t2\tnsubj\t_\t_",
      "2\tworks\twork\tVERB\tVBZ\tNumber=Sing\t0\troot\t_\t_",
      "3\tin\tin\tADP\tIN\t_\t4\tcase\t_\t_",
      "4\tParis\tParis\tPROPN\tNNP\tNumber=Sing\t2\tobl\t_\t_",
      "5\tand\tand\tCCONJ\tCC\t_\t6\tcc\t_\t_",
      "6\tLondon\tLondon\tPROPN\tNNP\tNumber=Sing\t4\tconj\t_\tSpaceAfter=No",
      "7\t.\t.\tPUNCT\t.\t_\t2\tpunct\t_\t_",
      "",
      "# sent_id = mwt",
      "# text = it's fine",
      "1-2\tit's\t_\t_\t_\t_\t_\t_\t_\tGloss=it+is",
      "1\tit\tit\tPRON\tPRP\tNumber=Sing\t3\tnsubj\t_\t_",
      "2\t's\tbe\tAUX\tVBZ\tNumber=Sing\t3\tcop\t_\t_",
      "3\tfine\tfine\tADJ\tJJ\t_\t0\troot\t_\tSpaceAfter=No",
      "",
      "");

  /** Run the converter over the fixture, with any extra properties as name, value pairs */
  static String convert(String... properties) throws Exception {
    File file = IOUtils.writeStringToTempFile(FIXTURE, "convertertest", "UTF-8");
    file.deleteOnExit();
    try {
      Properties props = new Properties();
      props.setProperty("conlluFile", file.getPath());
      for (int i = 0; i < properties.length; i += 2) {
        props.setProperty(properties[i], properties[i + 1]);
      }
      ByteArrayOutputStream bytes = new ByteArrayOutputStream();
      try (PrintStream out = new PrintStream(bytes, true, "UTF-8")) {
        UniversalDependenciesConverter.convert(props, out);
      }
      return bytes.toString("UTF-8");
    } finally {
      file.delete();
    }
  }

  /** The lines of a written treebank, ending with the blank line after the last sentence */
  static String written(String... lines) {
    StringBuilder text = new StringBuilder();
    for (String line : lines) {
      text.append(line).append(System.lineSeparator());
    }
    text.append(System.lineSeparator());
    return text.toString();
  }

  /**
   * The basic conversion
   *<br>
   * Every DEPS column is empty here, which
   * testBasicHasNoEnhancedDependencies says on its own.
   */
  @Test
  public void testBasic() throws Exception {
    assertEquals(written(
        "# sent_id = 0",
        "# sent_id = relcl",
        "# text = the man who I saw left",
        "1\tthe\tthe\tDET\tDT\tDefinite=Def\t2\tdet\t_\t_",
        "2\tman\tman\tNOUN\tNN\tNumber=Sing\t6\tnsubj\t_\t_",
        "3\twho\twho\tPRON\tWP\tPronType=Rel\t5\tobj\t_\t_",
        "4\tI\tI\tPRON\tPRP\tNumber=Sing\t5\tnsubj\t_\t_",
        "5\tsaw\tsee\tVERB\tVBD\tTense=Past\t2\tacl:relcl\t_\t_",
        "6\tleft\tleave\tVERB\tVBD\tTense=Past\t0\troot\t_\t_",
        "",
        "# sent_id = 1",
        "# sent_id = coord",
        "# text = He works in Paris and London.",
        "1\tHe\the\tPRON\tPRP\tNumber=Sing\t2\tnsubj\t_\t_",
        "2\tworks\twork\tVERB\tVBZ\tNumber=Sing\t0\troot\t_\t_",
        "3\tin\tin\tADP\tIN\t_\t4\tcase\t_\t_",
        "4\tParis\tParis\tPROPN\tNNP\tNumber=Sing\t2\tobl\t_\t_",
        "5\tand\tand\tCCONJ\tCC\t_\t6\tcc\t_\t_",
        "6\tLondon\tLondon\tPROPN\tNNP\tNumber=Sing\t4\tconj\t_\tSpaceAfter=No",
        "7\t.\t.\tPUNCT\t.\t_\t2\tpunct\t_\t_",
        "",
        "# sent_id = 2",
        "# sent_id = mwt",
        "# text = it's fine",
        "1-2\tit's\t_\t_\t_\t_\t_\t_\t_\tGloss=it+is",
        "1\tit\tit\tPRON\tPRP\tNumber=Sing\t3\tnsubj\t_\t_",
        "2\t's\tbe\tAUX\tVBZ\tNumber=Sing\t3\tcop\t_\t_",
        "3\tfine\tfine\tADJ\tJJ\t_\t0\troot\t_\tSpaceAfter=No"),
        convert());
  }

  @Test
  public void testEnhanced() throws Exception {
    assertEquals(written(
        "# sent_id = 0",
        "# sent_id = relcl",
        "# text = the man who I saw left",
        "1\tthe\tthe\tDET\tDT\tDefinite=Def\t2\tdet\t2:det\t_",
        "2\tman\tman\tNOUN\tNN\tNumber=Sing\t6\tnsubj\t5:obj|6:nsubj\t_",
        "3\twho\twho\tPRON\tWP\tPronType=Rel\t5\tobj\t2:ref\t_",
        "4\tI\tI\tPRON\tPRP\tNumber=Sing\t5\tnsubj\t5:nsubj\t_",
        "5\tsaw\tsee\tVERB\tVBD\tTense=Past\t2\tacl:relcl\t2:acl:relcl\t_",
        "6\tleft\tleave\tVERB\tVBD\tTense=Past\t0\troot\t0:root\t_",
        "",
        "# sent_id = 1",
        "# sent_id = coord",
        "# text = He works in Paris and London.",
        "1\tHe\the\tPRON\tPRP\tNumber=Sing\t2\tnsubj\t2:nsubj\t_",
        "2\tworks\twork\tVERB\tVBZ\tNumber=Sing\t0\troot\t0:root\t_",
        "3\tin\tin\tADP\tIN\t_\t4\tcase\t4:case\t_",
        "4\tParis\tParis\tPROPN\tNNP\tNumber=Sing\t2\tobl\t2:obl:in\t_",
        "5\tand\tand\tCCONJ\tCC\t_\t6\tcc\t6:cc\t_",
        "6\tLondon\tLondon\tPROPN\tNNP\tNumber=Sing\t4\tconj\t2:obl:in|4:conj:and\tSpaceAfter=No",
        "7\t.\t.\tPUNCT\t.\t_\t2\tpunct\t2:punct\t_",
        "",
        "# sent_id = 2",
        "# sent_id = mwt",
        "# text = it's fine",
        "1-2\tit's\t_\t_\t_\t_\t_\t_\t_\tGloss=it+is",
        "1\tit\tit\tPRON\tPRP\tNumber=Sing\t3\tnsubj\t3:nsubj\t_",
        "2\t's\tbe\tAUX\tVBZ\tNumber=Sing\t3\tcop\t3:cop\t_",
        "3\tfine\tfine\tADJ\tJJ\t_\t0\troot\t0:root\tSpaceAfter=No"),
        convert("outputRepresentation", "enhanced"));
  }

  @Test
  public void testEnhancedPlusPlus() throws Exception {
    // nothing in this fixture is treated differently by enhanced++, so the
    // two come out the same.  a fixture which told them apart would be
    // worth having
    assertEquals(convert("outputRepresentation", "enhanced"),
                 convert("outputRepresentation", "enhanced++"));
  }

  @Test
  public void testReplaceLemmata() throws Exception {
    // the lemmata in the fixture are already the ones Morphology produces,
    // so replacing them changes nothing here
    assertEquals(convert("outputRepresentation", "enhanced"),
                 convert("outputRepresentation", "enhanced", "replaceLemmata", "true"));
  }

  @Test
  public void testBasicHasNoEnhancedDependencies() throws Exception {
    // a basic treebank says nothing in its DEPS column: the enhanced graph
    // is what fills that in, and a basic conversion has none
    for (String line : convert().split("\\R")) {
      if (line.startsWith("#") || line.isEmpty()) {
        continue;
      }
      String[] fields = line.split("\t");
      assertEquals(line, "_", fields[8]);
    }
  }

  @Test
  public void testMultiWordTokenMiscIsKept() throws Exception {
    // the misc of an MWT range line comes through the reader and out the
    // writer.  SpaceAfter=No lives there in a great many treebanks
    for (String written : new String[] {convert(), convert("outputRepresentation", "enhanced")}) {
      assertTrue(written, written.contains("1-2\tit's\t_\t_\t_\t_\t_\t_\t_\tGloss=it+is"));
    }
  }

  /**
   * Run the converter with a text file as well, one line of text per sentence
   */
  static String convertWithText(String text, String... properties) throws Exception {
    File textFile = IOUtils.writeStringToTempFile(text, "convertertext", "UTF-8");
    textFile.deleteOnExit();
    try {
      String[] withText = new String[properties.length + 2];
      System.arraycopy(properties, 0, withText, 0, properties.length);
      withText[properties.length] = "textFile";
      withText[properties.length + 1] = textFile.getPath();
      return convert(withText);
    } finally {
      textFile.delete();
    }
  }

  /** The misc of the word with this form, in the first sentence it turns up in */
  private static String miscOf(String written, String word) {
    for (String line : written.split("\\R")) {
      String[] fields = line.split("\t");
      if (fields.length == 10 && fields[1].equals(word)) {
        return fields[9];
      }
    }
    return null;
  }

  @Test
  public void testTextFileSetsTheSpacing() throws Exception {
    // the text says where the spaces are, and the spacing comes back out in
    // the misc column.  the fixture's own SpaceAfter is replaced by what
    // the text says, not added to it
    String text = String.join("\n",
        "the man who I saw left",
        "He works in Paris and London.",
        "it's fine",
        "");
    String written = convertWithText(text);
    assertEquals("_", miscOf(written, "Paris"));
    assertEquals("SpaceAfter=No", miscOf(written, "London"));
    assertEquals("_", miscOf(written, "."));
  }

  @Test
  public void testTextFileWithWiderSpacing() throws Exception {
    // two spaces between two words is not the same as one, and says so
    String text = String.join("\n",
        "the man who I saw left",
        "He works in  Paris and London.",
        "it's fine",
        "");
    String written = convertWithText(text);
    assertEquals("SpacesAfter=\\s\\s", miscOf(written, "in"));
  }

  @Test
  public void testTextFileWhichDoesNotMatch() throws Exception {
    // the second line of text is not the second sentence, so its words
    // cannot be found there, and the converter stops with an error rather
    // than taking the spacing of the sentence from the wrong text
    String text = String.join("\n",
        "the man who I saw left",
        "something else entirely",
        "it's fine",
        "");
    try {
      convertWithText(text);
      fail("Expected a text which does not match the sentence to be reported");
    } catch (RuntimeException e) {
      assertTrue(e.getMessage(), e.getMessage().contains("Cannot find word"));
    }
  }

  @Test
  public void testTheConverterWritesItsOwnSentenceIds() throws Exception {
    // the converter numbers the sentences itself, and the writer prints the
    // comments the file came with, so a CoNLL-U input gives two sent_id
    // lines for each sentence
    String written = convert();
    assertTrue(written, written.contains("# sent_id = 0"));
    assertTrue(written, written.contains("# sent_id = relcl"));
  }
